/** Full logo as on remocn.dev: R mark (0.76em, on the baseline) + "emocn" in Manrope 600. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

// gradients.sh "grain" palette: the stat block that locks the poster.
const GRAIN = ["#ffd8b4", "#e0703b", "#8a2c1d", "#2b1015"] as const;
const GRAIN_BG = "#070505";

interface ShapePackProps {
  value?: number;
  decimals?: number;
  suffix?: string;
  label?: string;
  logo?: React.ReactNode;
  accent?: string;
  /** Color of the stat number. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the stat and label. Load it yourself; Bricolage Grotesque by default. */
  fontFamily?: string;
  /** Frames each block takes to fall into place. */
  fall?: number;
  /** Corner radius of the blocks, in px at 720p. */
  radius?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Size of the poster, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
}

interface Block {
  key: string;
  c: number;
  r: number;
  w: number;
  h: number;
  tone: number;
  at: number;
}

const COLS = 12;
const ROWS = 8;
