const ELEMENT_PROP_KEYS = new Set(["theme","suffix","label","value","decimals","fall","radius","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  suffix: "×",
  label: "faster renders",
  value: 3.2,
  decimals: 1,
  fall: 14,
  radius: 2,
  accent: "#3B5BFD",
  fontFamily: "Bricolage Grotesque",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type ShapePackElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShapePackBase>;

const ShapePackInner = forwardRef<
  HTMLDivElement,
  ShapePackElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShapePack>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShapePackBase
          {...(componentProps as unknown as ComponentProps<typeof ShapePackBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShapePack = Interactive.withSchema({
  Component: ShapePackInner,
  componentName: "<ShapePack>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
